				'status'        => 'active',
				'created_at'    => gmdate( 'Y-m-d H:i:s', $now ),
				'expires_at'    => gmdate( 'Y-m-d H:i:s', $expires_ts ),
			),
			array( '%s','%s','%s','%s','%d','%s','%s','%s','%s','%s','%s','%s' )
		);

		if ( ! $inserted ) {
			return false;
		}
		return $raw_token;
