	/**
	 * POST — consume token, login, session regen, redirect.
	 */
	private static function process_login( $token ) {
		// Nonce patikra (CSRF)
		$nonce = isset( $_POST['ps_nonce'] ) ? sanitize_text_field( wp_unslash( $_POST['ps_nonce'] ) ) : '';
		if ( ! wp_verify_nonce( $nonce, 'ps_magic_login' ) ) {
			self::render_error( 'Sesija pasibaigusi. Prašome prisijungti iš naujo.' );
			return;
		}

		$result = ps_consume_token( $token );
		if ( ! $result['valid'] ) {
			// S209: ne aklas klaidos puslapis — ta pati email forma su galimybe gauti nauja nuoroda.
			self::render_retry( 'Ši nuoroda nebegalioja arba jau panaudota. Įveskite el. paštą ir atsiųsime naują.' );
			return;
		}
		if ( isset( $result['row']->purpose ) && $result['row']->purpose !== self::TOKEN_PURPOSE ) {
			self::render_retry( 'Nuoroda neteisinga. Įveskite el. paštą ir atsiųsime naują.' );
			return;
		}

		$user_id = (int) $result['row']->subject_id;
		$user    = $user_id ? get_user_by( 'id', $user_id ) : null;

		// S207: email-only token (subject_id=0) — paskyra kuriama TIK cia.
		if ( ! $user ) {
			$token_email = isset( $result['row']->subject_email ) ? sanitize_email( $result['row']->subject_email ) : '';
			if ( ! $token_email || ! is_email( $token_email ) ) {
				self::render_error( 'Paskyra nerasta.' );
				return;
			}
			// Tarp issiuntimo ir paspaudimo paskyra galejo atsirasti (registracija/Google login)
			$user = get_user_by( 'email', $token_email );
			if ( ! $user ) {
				$new_id = wp_create_user(
					self::unique_login_from_email( $token_email ),
					wp_generate_password( 24 ),
					$token_email
				);
				if ( is_wp_error( $new_id ) ) {
					self::render_error( 'Nepavyko sukurti paskyros. Bandykite dar kartą.' );
					return;
				}
				$new_user = new WP_User( $new_id );
				$new_user->set_role( 'customer' );
				$user = get_user_by( 'id', $new_id );
			}
			if ( ! $user ) {
				self::render_error( 'Paskyra nerasta.' );
				return;
			}
		}
		$user_id = (int) $user->ID;

		// Session fixation apsauga: wp_clear_auth_cookie + naujas wp_set_auth_cookie
		// zemiau duoda nauja auth cookie (sena negalioja). WP neturi PHP session'u
		// pagal nutylejima, tad atskiro session_regenerate_id nereikia.

		// Login
		wp_clear_auth_cookie();
		wp_set_current_user( $user_id );
		wp_set_auth_cookie( $user_id, true );  // remember=true
		do_action( 'wp_login', $user->user_login, $user );

		// PS_EMAIL_VERIFIED mirror
		update_user_meta( $user_id, self::META_EMAIL_VERIFIED, 'yes' );
		// Push i Sender (jei yra)
		if ( function_exists( 'ps_esp_adapter' ) ) {
			$adapter = ps_esp_adapter();
			if ( $adapter && $adapter->is_configured() ) {
				$adapter->upsert_contact( $user->user_email, array(
					'PS_EMAIL_VERIFIED' => 'true',
					'PS_LOGIN_METHOD'   => 'magic_link',
				) );
			}
		}

		// S209: redirect pagal tai, is kur zmogus atejo (token action laukas).
		//   pet     -> augintinio puslapis (ten gyvena juodrascio perkelimas, S207)
		//   account -> paskyros pradzia (iprastas login is /my-account/)
		$context = isset( $result['row']->action ) ? (string) $result['row']->action : 'pet';
		$redirect = '';
		if ( $context !== 'account' && function_exists( 'wc_get_account_endpoint_url' ) ) {
			$redirect = wc_get_account_endpoint_url( 'augintinis' );
		}
		if ( ! $redirect ) {
			$redirect = wc_get_page_permalink( 'myaccount' );
		}
		if ( ! $redirect ) {
			$redirect = home_url( '/' );
		}
		wp_safe_redirect( $redirect );
		exit;
	}

